sub('src/lib/slug.ts','''/** Project keys are the short''','''/** Project keys never exceed this many characters. */
export const PROJECT_KEY_MAX_LENGTH = 4;

/**
 * Makes `key` unique among `taken` the way `uniqueSlug` does for addresses:
 * by appending `2`, `3`, … and trimming the base so the result never exceeds
 * `PROJECT_KEY_MAX_LENGTH` characters.
 */
export function uniqueProjectKey(key: string, taken: Iterable<string>): string {
  const used = new Set(taken);
  if (!used.has(key)) return key;

  for (let suffix = 2; suffix < 100_000; suffix += 1) {
    const tail = String(suffix);
    const candidate = `${key.slice(0, Math.max(1, PROJECT_KEY_MAX_LENGTH - tail.length))}${tail}`;
    if (candidate.length <= PROJECT_KEY_MAX_LENGTH && !used.has(candidate)) {
      return candidate;
    }
  }
  throw new InvalidSlugError(key, "exhausted unique key suffixes");
}

